"""Human-readable coordination on top of versioned, permission-bound records."""

COORDINATION_CSS = r"""
.co-page{max-width:1280px;margin:auto}.co-head{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:24px}.co-head h1{font-size:28px;margin:6px 0}.co-head p,.co-note{color:var(--mut);line-height:1.8;margin:8px 0}.co-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.co-layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(280px,.8fr);gap:28px;align-items:start}.co-panel{padding:22px;background:var(--panel);border:1px solid var(--line);border-radius:8px;min-width:0}.co-panel h2{font-size:19px;margin:0 0 14px}.co-panel h3{font-size:16px;margin:8px 0}.co-form{display:grid;gap:14px}.co-form label{display:flex;flex-direction:column;gap:7px;font-size:13px}.co-form input,.co-form select,.co-form textarea{width:100%;min-width:0}.co-form textarea{min-height:84px;resize:vertical}.co-form .co-check{flex-direction:row;align-items:center}.co-form .co-check input{width:auto}.co-two{display:grid;grid-template-columns:1fr 1fr;gap:14px}.co-form .co-source-input{min-height:230px}.co-record{padding:20px 0;border-top:1px solid var(--line);overflow-wrap:anywhere}.co-record:first-child{border-top:0}.co-record h3{margin:0 0 10px}.co-record p,.co-full{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8}.co-meta{display:flex;gap:8px 16px;flex-wrap:wrap;font-size:12px;color:var(--mut);line-height:1.8}.co-state{padding:3px 7px;border:1px solid var(--line);border-radius:4px;color:var(--fg)}.co-state[data-state=stale],.co-error{color:var(--bad)}.co-state[data-state=checked]{color:var(--ok)}.co-error{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8}.co-notice{margin:12px 0;line-height:1.8;white-space:pre-wrap}.co-facts{display:grid;grid-template-columns:100px minmax(0,1fr);gap:9px;margin:14px 0}.co-facts dt{color:var(--mut)}.co-facts dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.co-empty{padding:24px 0;color:var(--mut);line-height:1.8}.co-source{margin:20px 0;border-top:1px solid var(--line);padding-top:16px}.co-source summary{cursor:pointer;font-weight:500}.co-source pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.8}.co-summary{margin:20px 0}.co-summary .co-layout{grid-template-columns:1fr}.co-summary .co-panel{padding:18px}.co-coverage{margin-top:28px}.co-coverage .co-head{margin-bottom:12px}.co-coverage .co-head h2{margin:0}.co-coverage .co-layout{grid-template-columns:1fr}.co-stats{display:flex;gap:10px 18px;flex-wrap:wrap;font-size:13px;margin:12px 0}.co-stats span{white-space:nowrap}.co-disabled{color:var(--mut);line-height:1.7}.co-list-link{display:block;text-decoration:none;padding:18px 0;border-top:1px solid var(--line)}.co-list-link b{display:block;font-size:16px;margin-bottom:8px}.co-form :is(button,input,select,textarea):focus-visible,.co-record button:focus-visible{outline:2px solid var(--blue);outline-offset:3px}.co-form button,.co-actions button,.co-actions a{min-height:40px}.co-project{display:flex;gap:12px;align-items:center;margin:18px 0}.co-project select{max-width:100%}@media(max-width:800px){.co-layout{grid-template-columns:1fr}.co-head{flex-direction:column;gap:10px}.co-head h1{font-size:25px}.co-panel{padding:18px}.co-two{grid-template-columns:1fr}.co-facts{grid-template-columns:1fr;gap:4px}.co-facts dd{margin-bottom:10px}.co-form input,.co-form select,.co-form textarea{font-size:16px}.co-actions button,.co-form button{min-height:44px}.co-project{align-items:stretch;flex-direction:column}.co-coverage,.co-summary{min-width:0}}
"""

COORDINATION_JS = r"""
const COORD={views:new Map(),drafts:new Map(),pending:new Map(),serial:0};
const coStatus={missing:'缺少材料',pending:'待人工核对',checked:'已核对材料',stale:'来源已变化',withdrawn:'已撤回',draft:'待补齐',published:'已发布任务',candidate:'规则草稿'};
function coIdentity(project,kind,id){return JSON.stringify([typeof ACCESS==='undefined'?'':ACCESS.base,S.meta?.user||'',project,kind,String(id||'')])}
function coLoad(key,kind){try{return JSON.parse(sessionStorage.getItem('tmh.co.'+kind+'.'+key)||'null')}catch(e){COORD.storageError='浏览器无法读取本地草稿或保存回执。为避免重复创建，请保留输入并重新加载页面恢复。';return null}}
function coPersist(key,kind,value){try{if(value===null)sessionStorage.removeItem('tmh.co.'+kind+'.'+key);else sessionStorage.setItem('tmh.co.'+kind+'.'+key,JSON.stringify(value))}catch(e){throw Error('浏览器无法保存草稿；请先复制输入再继续。')}}
function coPending(key){if(!COORD.pending.has(key)){const p=coLoad(key,'pending');if(p)COORD.pending.set(key,{...p,busy:false})}return COORD.pending.get(key)}
function coDraft(v,initial={}){if(!COORD.drafts.has(v.key))COORD.drafts.set(v.key,coLoad(v.key,'draft')||initial);return COORD.drafts.get(v.key)}
function coRemember(v,draft){if(draft.action&&!draft._slot)draft._slot=draft.action+':'+(draft.action_id??draft.item_id??'new');COORD.drafts.set(v.key,draft);coPersist(v.key,'draft',draft);if(draft._slot)coPersist(v.key+'#'+draft._slot,'draft',draft)}
function coSwitchDraft(v,initial){try{coCapture(v);const slot=initial.action+':'+(initial.action_id??initial.item_id??'new');coRemember(v,coLoad(v.key+'#'+slot,'draft')||{...initial,_slot:slot});coRender(v);v.host.querySelector('[data-co-field]')?.focus()}catch(e){coNotice(v,e.message,true)}}
function coLive(v){return COORD.views.get(v.key)===v&&v.host.isConnected&&v.route===location.hash&&v.live()&&!(typeof ACCESS!=='undefined'&&ACCESS.blocked)&&v.epoch===(typeof ACCESS==='undefined'?0:ACCESS.epoch)}
function coCurrent(v){const now=COORD.views.get(v.key);return now&&coLive(now)?now:null}
function coWritable(project){return !!S.meta?.login&&(typeof accessCanWrite!=='function'||accessCanWrite(project))}
function coView(host,project,kind,id,path,paint,live=()=>true){const key=coIdentity(project,kind,id),v={host,project,kind,id,path,paint,live,key,route:location.hash,epoch:typeof ACCESS==='undefined'?0:ACCESS.epoch,read:0,data:null,message:'',error:false};COORD.views.set(key,v);return v}
function coField(name,label,value='',type='text',extra=''){return `<label>${h(label)}${type==='textarea'?`<textarea data-co-field="${h(name)}" ${extra}>${h(value)}</textarea>`:`<input data-co-field="${h(name)}" type="${type}" value="${h(value)}" ${extra}>`}</label>`}
function coMembers(name,label,value,members){const valid=(members||[]).some(m=>String(m.id??m.name)===value);return `<label>${h(label)}<select data-co-field="${name}"><option value="">未明确</option>${(members||[]).map(m=>`<option value="${h(m.id??m.name)}" ${String(m.id??m.name)===value?'selected':''}>${h(m.name||m.id)}</option>`).join('')}${value&&!valid?`<option value="${h(value)}" selected>${h(value)}（当前不可用，请重选）</option>`:''}</select></label>`}
function coCapture(v){const draft=coDraft(v);v.host.querySelectorAll('[data-co-field]').forEach(el=>{const name=el.dataset.coField,value=el.type==='checkbox'?el.checked:el.value;if(name==='body'&&draft._originalBody!==undefined&&String(value).replace(/\r\n?/g,'\n')===draft._originalBody.replace(/\r\n?/g,'\n'))draft[name]=draft._originalBody;else{draft[name]=value;if(name==='body')delete draft._originalBody}});coRemember(v,draft);return draft}
function coNotice(v,text,error=false){v.message=text;v.error=error;if(!coLive(v))return;const n=v.host.querySelector('[data-co-notice]');if(n){n.textContent=text;n.className='co-notice'+(error?' co-error':'')}}
function coCommon(v){const pending=coPending(v.key);return `${COORD.storageError?'<p class="co-error" role="alert">'+h(COORD.storageError)+'</p>':''}<p data-co-notice class="co-notice${v.error?' co-error':''}" role="status" aria-live="polite">${h(v.message)}</p>${pending?`<div class="co-error" role="status"><p>${pending.completed?'服务器已保存，正在完成本地记录整理；不会重复创建。':pending.busy?'正在保存，请勿重复提交。':'尚未确认服务器是否保存。输入与原请求已保留。'}</p><button data-co-retry ${pending.busy?'disabled':''}>${pending.completed?'继续显示已保存记录':'用原请求核对结果'}</button></div>`:''}`}
function coRender(v){if(!coLive(v))return;if(!v.data){v.host.innerHTML='<p class="co-note">记录暂不可读取。</p>'+coCommon(v)+'<button data-co-refresh>重试读取</button>';coBind(v);return}const focused=document.activeElement,field=v.host.contains?.(focused)?focused.dataset?.coField:null,start=focused?.selectionStart,end=focused?.selectionEnd;v.paint(v);if(field){const el=v.host.querySelector('[data-co-field="'+field+'"]');el?.focus();if(el&&typeof start==='number')try{el.setSelectionRange(start,end)}catch(e){}}}
function coBind(v){const draft=coDraft(v);v.host.querySelectorAll('[data-co-field]').forEach(el=>{if(el.tagName==='TEXTAREA'&&draft[el.dataset.coField]!==undefined)el.value=draft[el.dataset.coField];el.oninput=()=>{try{coCapture(v)}catch(e){coNotice(v,e.message,true)}}});const pending=coPending(v.key);const retry=v.host.querySelector('[data-co-retry]');if(pending&&retry)retry.onclick=()=>coPerform(v,pending);const refresh=v.host.querySelector('[data-co-refresh]');if(refresh)refresh.onclick=()=>coRefresh(v);if(pending)v.host.querySelectorAll('input,select,textarea,button[data-co-write]').forEach(n=>n.disabled=true)}
async function coRefresh(v){const serial=++v.read;if(!coLive(v))return;coNotice(v,'正在读取记录…');try{const data=await get(v.kind==='meetings'?v.path+'?offset='+(v.offset||0):v.path);if(!coLive(v)||serial!==v.read)return;if(!data||typeof data!=='object'||(v.kind!=='meetings'&&!Number.isInteger(data.revision)))throw Error('服务器返回的记录不完整');if(v.kind==='meetings')data.revision=0;if(v.data)coCapture(v);v.data=data;v.needsRefresh=false;v.message='';v.error=false;coRender(v)}catch(e){if(coLive(v)&&serial===v.read){v.message=e.message;v.error=true;if(v.data)coRender(v);else coRender(v)}}}
async function coWrite(v,body,success=null,keepDraft=false){if(!coLive(v)||!coWritable(v.project)||coPending(v.key)||v.needsRefresh)return;if(COORD.storageError){coNotice(v,COORD.storageError,true);return}try{coCapture(v)}catch(e){coNotice(v,e.message,true);return}const pending={path:v.path,body:{...body,request_id:globalThis.crypto?.randomUUID?.()||'co-'+Date.now()+'-'+(++COORD.serial)},busy:false,success,keepDraft,slot:coDraft(v)._slot};try{coPersist(v.key,'pending',{path:pending.path,body:pending.body,keepDraft,slot:pending.slot})}catch(e){coNotice(v,e.message,true);return}COORD.pending.set(v.key,pending);return coPerform(v,pending)}
async function coPerform(v,p){if(p.busy)return;p.busy=true;let current=coCurrent(v);if(current)coRender(current);try{const result=p.completed||await post(p.path,p.body),receipt=result?.receipt;if(!receipt||receipt.request_id!==p.body.request_id||!Number.isInteger(receipt.revision)||!Number.isInteger(result.revision)||(v.kind==='meetings'&&!result.meeting?.id)||(['content_create','content'].includes(v.kind)&&!result.delivery?.id))throw Error('服务器保存回执不完整');p.completed=result;current=coCurrent(v);if(current)current.needsRefresh=true;if(!p.keepDraft){COORD.drafts.delete(v.key);coPersist(v.key,'draft',null);if(p.slot)coPersist(v.key+'#'+p.slot,'draft',null)}coPersist(v.key,'pending',null);COORD.pending.delete(v.key);current=coCurrent(v);if(!current)return;current.message='已保存记录。';current.needsRefresh=true;current.data=null;if(current.kind==='content_create'){ls.set('tmh.delivery.create',null);location.hash=dlHref(result.delivery.id);return}if(current.kind==='content'){ls.set('tmh.delivery.artifact.'+current.deliveryId+'.'+current.stage,null);vDelivery(current.deliveryId,current.stage);return}if(current.kind==='meetings'&&result.meeting?.id){location.hash='#/meetings/'+encodeURIComponent(result.meeting.id)+'/'+encodeURIComponent(current.project);return}if(p.success){p.success(result);return}await coRefresh(current)}catch(e){current=coCurrent(v);if(e.access)return;if(!p.completed&&[400,401,403,404,409,413,422,429].includes(e.status)){try{coPersist(v.key,'pending',null);COORD.pending.delete(v.key)}catch(cleanup){e=cleanup}}if(current){current.message=e.message+(coPending(v.key)?' 请用原请求核对结果。':' 输入已保留；刷新并核对最新记录后再提交。');current.error=true}}finally{p.busy=false;current=coCurrent(v);if(current)coRender(current)}}
function coBound(v,draft,token){return !v.needsRefresh&&draft.revision===v.data.revision&&(token===undefined||draft.source_token===token)}
function coRebind(v,draft,token){coRemember(v,{...draft,revision:v.data.revision,...(token===undefined?{}:{source_token:token})});coRender(v)}
function coEditorState(v,draft,allowed,token){const stale=!coBound(v,draft,token);return `<p class="co-note">${!coWritable(v.project)?'当前账号只有查看权限，或尚未登录个人账号。':!allowed?'当前状态不允许修改。':stale?'来源或记录已变化。输入保留，请先核对最新内容。':'保存只登记本项记录，不替代技术检查、人工验收或关单。'}</p>${stale?'<button type="button" data-co-rebind>保留草稿，核对最新依据</button>':''}`}
function coFinishForm(v,draft,allowed,submit,token){coBind(v);if(!allowed||!coWritable(v.project))v.host.querySelectorAll('input,select,textarea').forEach(n=>n.disabled=true);const form=v.host.querySelector('[data-co-form]');if(form)form.onsubmit=e=>{e.preventDefault();if(!coWritable(v.project)||!allowed||!coBound(v,draft,token)||coPending(v.key))return;try{return submit(coCapture(v))}catch(e){coNotice(v,e.message,true)}};const rebind=v.host.querySelector('[data-co-rebind]');if(rebind)rebind.onclick=()=>{try{coRebind(v,coCapture(v),token)}catch(e){coNotice(v,e.message,true)}};v.host.querySelectorAll('[data-co-write]').forEach(n=>n.disabled=!!COORD.storageError||!!coPending(v.key)||!coWritable(v.project)||!allowed||!coBound(v,draft,token))}
function coSource(label,value){return `<details class="co-source"><summary>${h(label)}</summary><pre>${h(typeof value==='string'?value:JSON.stringify(value,null,2))}</pre></details>`}

function meetingProject(key){if(!S.projects.some(p=>p.key===key))return;setProj(key);S.scope=key;ls.set('tmh.scope',key);paintSel();if(location.hash==='#/meetings')return vMeetings();location.hash='#/meetings'}
async function vMeetings(id='',requestedProject=''){
 if(requestedProject){if(!S.projects.some(p=>p.key===requestedProject)){$('#main').innerHTML='<section class="co-page"><h1>无法读取会议</h1><p class="co-error">链接所指项目不在当前授权范围。请返回项目列表。</p><a href="#/projects">返回项目列表</a></section>';return}setProj(requestedProject);S.scope=requestedProject;ls.set('tmh.scope',requestedProject);paintSel()}
 const project=S.scope&&S.scope!=='*'?S.scope:'';if(!project||!S.projects.some(p=>p.key===project)){$('#main').innerHTML=`<section class="co-page"><div class="co-head"><div><a href="#/workspace">返回工作台</a><h1>会议与行动</h1><p>选择实际项目，记录会议原文与会后行动。不会跨项目读取会议或发送通知。</p></div></div><label class="co-project">项目<select id="coProject"><option value="">请选择项目</option>${S.projects.map(p=>`<option value="${h(p.key)}">${h(p.name)} · ${h(p.key)}</option>`).join('')}</select></label></section>`;$('#coProject').onchange=e=>meetingProject(e.target.value);return}
 const host=$('#main');host.innerHTML='<section class="co-page" id="coMeetingHost"><p class="co-note">正在读取会议记录…</p></section>';const kind=id?'meeting':'meetings',v=coView($('#coMeetingHost'),project,kind,id,'/api/projects/'+encodeURIComponent(project)+'/meetings'+(id?'/'+encodeURIComponent(id):''),id?meetingPaint:meetingsPaint,()=>S.scope===project);await coRefresh(v);
}
function meetingHeader(v,title,description){return `<header class="co-head"><div><a href="${v.kind==='meeting'?'#/meetings':'#/workspace'}">${v.kind==='meeting'?'返回会议列表':'返回工作台'}</a><p class="co-note">${h(v.project)}</p><h1>${h(title)}</h1><p>${h(description)}</p></div><button data-co-refresh>刷新记录</button></header>`}
async function meetingImport(v,file){if(!file)return;try{const draft=coCapture(v),before=draft.body||'',seq=v.fileRead=(v.fileRead||0)+1;if(!/\.txt$/i.test(file.name))throw Error('请选择 UTF-8 编码的 .txt 文件。');const text=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await file.arrayBuffer());if(!coLive(v)||seq!==v.fileRead)return;if((coDraft(v).body||'')!==before)throw Error('读取文件时正文已改变，保留当前输入。请再次选择文件导入。');coRemember(v,{...coDraft(v),body:text,_originalBody:text});coRender(v);coNotice(v,'已读取完整文件：'+file.name+'。保存前请核对项目和原文。')}catch(e){if(coLive(v))coNotice(v,e instanceof TypeError?'文件不是有效 UTF-8，未导入。请先转换编码后重试。':e.message,true)}}
function meetingsPaint(v){const d=v.data;if(!d)return;const draft=coDraft(v,{revision:0,title:'',occurred_on:'',body:''}),allowed=d.can_edit;
 v.host.innerHTML=meetingHeader(v,'会议与行动','先保存原始记录，再明确行动、责任人和完成条件。')+coCommon(v)+`<div class="co-layout"><section><h2>项目会议</h2>${(d.items||[]).map(m=>`<a class="co-list-link" href="#/meetings/${encodeURIComponent(m.id)}/${encodeURIComponent(v.project)}"><b>${h(m.title)}</b><span class="co-meta">${h(m.occurred_on||'日期未登记')} · ${h(m.created_by||'')}<br>${h(m.action_counts?.published??0)} 项已发布任务 · ${h(m.action_counts?.draft??0)} 项待补齐</span></a>`).join('')||'<p class="co-empty">尚无会议记录。保存一份完整会议原文，或从手工行动开始。</p>'}<div class="co-actions"><button data-co-prev ${(d.offset||0)<=0?'disabled':''}>上一页</button><span>${h(d.total??0)} 场会议</span><button data-co-next ${(d.offset||0)+(d.items||[]).length>=(d.total||0)?'disabled':''}>下一页</button></div></section><section class="co-panel"><h2>记录一次会议</h2><form class="co-form" data-co-form>${coField('title','会议标题',draft.title)}${coField('occurred_on','会议日期（可未知）',draft.occurred_on,'date')}<label>导入原始记录（UTF-8 .txt）<input data-co-import type="file" accept=".txt,text/plain"></label>${coField('body','完整会议原文',draft.body,'textarea','class="co-source-input"')}<p class="co-note">全文原样保存。只从明确的 TODO／待办标记提取规则草稿，仍需逐项核对；未提取到行动不代表会议没有待办。</p>${coEditorState(v,draft,allowed)}<button class="primary" data-co-write>保存会议原文</button></form></section></div>`;
 coFinishForm(v,draft,allowed,f=>coWrite(v,{title:f.title,occurred_on:f.occurred_on,body:f.body},r=>{location.hash='#/meetings/'+encodeURIComponent(r.meeting?.id||r.id)}));v.host.querySelector('[data-co-import]').onchange=e=>meetingImport(v,e.target.files?.[0]);v.host.querySelector('[data-co-import]').disabled=!coWritable(v.project)||!allowed||!!coPending(v.key);v.host.querySelector('[data-co-prev]').onclick=()=>{v.offset=Math.max(0,(d.offset||0)-(d.limit||50));coRefresh(v)};v.host.querySelector('[data-co-next]').onclick=()=>{v.offset=(d.offset||0)+(d.limit||50);coRefresh(v)};
}
function meetingEdit(v,item=null,action='add_action'){if(coPending(v.key))return;coSwitchDraft(v,{action,action_id:item?.id??null,revision:v.data.revision,title:item?.title||'',owner:item?.owner||'',due_date:item?.due_date||'',deliverable:item?.deliverable||'',criteria:item?.criteria||'',source_start:item?.source_start??'',source_end:item?.source_end??'',note:action==='withdraw_action'?'':item?.note||''})}
function meetingPaint(v){const d=v.data;if(!d)return;const m=d.meeting,draft=coDraft(v,{action:'add_action',revision:d.revision,title:'',owner:'',due_date:'',deliverable:'',criteria:'',source_start:'',source_end:'',note:''}),action=draft.action,item=(d.actions||[]).find(a=>a.id===draft.action_id),editing=['add_action','edit_action'].includes(action),allowed=d.can_edit&&(!item||item.status==='draft');
 v.host.innerHTML=meetingHeader(v,m.title,'把规则草稿补成可执行行动；发布会创建既有任务，仍按原验收流程推进。')+`<p class="co-meta">${h(m.occurred_on||'会议日期未登记')} · ${h(m.created_by)} · ${h(m.created)}</p>${coCommon(v)}${coSource('查看完整原始会议记录',m.body)}<p class="co-note">${h(m.extraction?.notice||'候选来自明确的待办标记，不代表模型理解或人工确认。')}</p><div class="co-layout"><section><div class="co-head"><h2>会后行动</h2><button data-co-add>手动新增行动</button></div>${(d.actions||[]).map(a=>`<article class="co-record"><div class="co-meta"><span class="co-state">${h(coStatus[a.status]||a.status)}</span>${a.source_start?`<span>来源第 ${h(a.source_start)}${a.source_end!==a.source_start?'–'+h(a.source_end):''} 行</span>`:'<span>手工登记</span>'}</div><h3>${h(a.title||'尚未填写行动')}</h3><dl class="co-facts"><dt>${a.ticket?'任务负责人':'约定负责人'}</dt><dd>${h((a.ticket?a.ticket.assignee:a.owner)||'待明确')}</dd><dt>期限</dt><dd>${h(a.due_date||'未约定')}</dd><dt>交付物</dt><dd>${h(a.deliverable||'待补齐')}</dd><dt>完成条件</dt><dd>${h(a.criteria||'待补齐')}</dd></dl>${a.source_quote?coSource('查看来源原话',a.source_quote):''}${a.note?`<p>${h(a.note)}</p>`:''}${a.withdraw_reason?`<p>撤回原因：${h(a.withdraw_reason)}</p>`:''}${a.ticket?`<a class="btn" href="#/t/${encodeURIComponent(a.ticket.key)}">查看任务 ${h(a.ticket.key)} · ${h(a.ticket.assignee||'待分配')}</a>`:''}<div class="co-actions">${a.status==='draft'?`<button data-co-action-id="${h(a.id)}" data-co-act="edit_action">补齐行动</button><button data-co-action-id="${h(a.id)}" data-co-act="publish_action">核对并发布任务</button><button data-co-action-id="${h(a.id)}" data-co-act="withdraw_action">撤回草稿</button>`:''}</div>${coSource('行动历史',a.history||[])}</article>`).join('')||'<p class="co-empty">没有提取到明确行动。可以阅读原文后手动添加；系统不会补造责任人或期限。</p>'}</section><aside class="co-panel"><h2>${{add_action:'新增行动',edit_action:'补齐行动',publish_action:'发布为任务',withdraw_action:'撤回行动'}[action]}</h2><form class="co-form" data-co-form>${editing?coField('title','要做什么',draft.title)+coMembers('owner','负责人（有效个人账号）',draft.owner,d.members)+coField('due_date','期限（未约定可留空）',draft.due_date,'date')+coField('deliverable','交付物',draft.deliverable,'textarea')+coField('criteria','什么结果算完成',draft.criteria,'textarea')+`<details><summary>标注来源行（可留空）</summary><div class="co-two">${coField('source_start','起始行',draft.source_start,'number','min="1"')}${coField('source_end','结束行',draft.source_end,'number','min="1"')}</div></details>`:action==='publish_action'?`<p>将「${h(item?.title||'')}」发布为任务。</p><p class="co-note">负责人：${h(item?.owner||'待明确')}<br>期限：${h(item?.due_date||'未约定')}</p><p class="co-full">交付物：${h(item?.deliverable||'待补齐')}<br>完成条件：${h(item?.criteria||'待补齐')}</p>`:`<p>${h(item?.title||'')}</p>`}${action==='publish_action'?'':coField('note',action==='withdraw_action'?'撤回原因':'补充说明',draft.note,'textarea')}${coEditorState(v,draft,allowed)}<button class="primary" data-co-write>${action==='publish_action'?'确认内容并发布任务':action==='withdraw_action'?'保存撤回原因':'保存行动草稿'}</button></form></aside></div>`;
 coFinishForm(v,draft,allowed,f=>coWrite(v,{action:f.action,revision:f.revision,...(f.action==='add_action'?{}:{action_id:f.action_id}),...(editing?{title:f.title,owner:f.owner,due_date:f.due_date,deliverable:f.deliverable,criteria:f.criteria,source_start:f.source_start?Number(f.source_start):null,source_end:f.source_end?Number(f.source_end):null,note:f.note}:f.action==='withdraw_action'?{note:f.note}:{})}));v.host.querySelector('[data-co-add]').onclick=()=>meetingEdit(v);v.host.querySelector('[data-co-add]').disabled=!d.can_edit||!coWritable(v.project)||!!coPending(v.key);v.host.querySelectorAll('[data-co-action-id]').forEach(b=>{b.disabled=!d.can_edit||!coWritable(v.project)||!!coPending(v.key);b.onclick=()=>meetingEdit(v,d.actions.find(a=>String(a.id)===b.dataset.coActionId),b.dataset.coAct)});
}
function briefingOpen(host,ticket,project,live=()=>true){const v=coView(host,project,'brief',ticket,'/api/tickets/'+encodeURIComponent(ticket)+'/brief',briefingPaint,live);host.innerHTML='<p class="co-note">正在读取工作简报…</p>';v.ready=coRefresh(v);return v}
function briefingPaint(v){const d=v.data;if(!d)return;const c=d.current,draft=coDraft(v,{revision:d.revision,source_token:d.source_token,summary:c?.summary||'',decisions:c?.decisions||'',next_step:c?.next_step||'',owner:c?.owner||'',due_date:c?.due_date||''}),allowed=d.can_edit;
 v.host.innerHTML=`<section class="co-summary"><div class="co-head"><div><h2>工作简报</h2><p class="co-note">先看结论与下一步，完整需求和来源继续保留。</p></div><button data-co-refresh>刷新简报</button></div>${coCommon(v)}${c?`<p class="co-meta">版本 ${h(c.revision)} · ${h(c.created_by)} · ${h(c.created)}</p>${c.stale?'<p class="co-error">这版简报的来源已变化，请核对最新任务与交接后保存新版。</p>':''}<dl class="co-facts"><dt>结论</dt><dd>${h(c.summary)}</dd><dt>待决定</dt><dd>${h(c.decisions||'未登记')}</dd><dt>下一步</dt><dd>${h(c.next_step||'未登记')}</dd><dt>下一步协作人</dt><dd>${h(c.owner||'未明确')}</dd><dt>期限</dt><dd>${h(c.due_date||'未约定')}</dd></dl>`:'<p class="co-empty">尚未保存工作简报。请根据真实情况填写；不会从长文中截断生成结论。</p>'}<details ${!c?'open':''}><summary>${c?'编写简报新版本':'编写工作简报'}</summary><form class="co-form" data-co-form>${coField('summary','结论',draft.summary,'textarea')}${coField('decisions','待决定',draft.decisions,'textarea')}${coField('next_step','下一步',draft.next_step,'textarea')}${coMembers('owner','下一步协作人（不改任务分配）',draft.owner,d.members)}${coField('due_date','期限（未约定可留空）',draft.due_date,'date')}${coEditorState(v,draft,allowed,d.source_token)}<button class="primary" data-co-write>保存简报新版本</button></form></details>${(d.history||[]).length?`<details class="co-source"><summary>历史简报（${d.history.length} 版）</summary>${d.history.map(b=>`<article class="co-record"><h3>版本 ${h(b.revision)}${b.stale?' · 来源已变化':''}</h3><p class="co-meta">${h(b.created_by)} · ${h(b.created)}</p><dl class="co-facts"><dt>结论</dt><dd>${h(b.summary)}</dd><dt>待决定</dt><dd>${h(b.decisions||'未登记')}</dd><dt>下一步</dt><dd>${h(b.next_step||'未登记')}</dd><dt>负责人 / 期限</dt><dd>${h(b.owner||'未明确')} / ${h(b.due_date||'未约定')}</dd></dl>${coSource('查看这版简报的完整来源',b.source)}</article>`).join('')}</details>`:''}${coSource('查看最新完整来源',d.source)}</section>`;
 coFinishForm(v,draft,allowed,f=>coWrite(v,{revision:f.revision,source_token:f.source_token,summary:f.summary,decisions:f.decisions,next_step:f.next_step,owner:f.owner,due_date:f.due_date}),d.source_token);
}

function coverageOpen(host,delivery,live=()=>true){const v=coView(host,delivery.project,'coverage',delivery.id,'/api/deliveries/'+encodeURIComponent(delivery.id)+'/coverage',coveragePaint,live);host.innerHTML='<p class="co-note">正在读取内容覆盖清单…</p>';v.ready=coRefresh(v);return v}
function coverageEdit(v,item=null,action='add'){if(coPending(v.key))return;coSwitchDraft(v,{action,item_id:item?.id??null,revision:v.data.revision,source_token:item?.source_token||'',title:item?.title||'',requirement:item?.requirement||'',required:item?.required??true,artifact_id:item?.artifact_id??'',note:action==='verify'||action==='withdraw'?'':item?.note||''})}
function coveragePaint(v){const d=v.data;if(!d)return;const draft=coDraft(v,{action:'add',revision:d.revision,title:'',requirement:'',required:true,artifact_id:'',note:''}),item=(d.items||[]).find(i=>i.id===draft.item_id),action=draft.action,editing=['add','update'].includes(action),allowed=d.can_edit&&(action!=='verify'||item?.can_verify),token=action==='verify'?item?.source_token:undefined;
 v.host.innerHTML=`<section class="co-coverage"><div class="co-head"><div><h2>内容覆盖检查</h2><p class="co-note">逐项核对要求与固定版本材料；核对材料不等于业务验收。</p></div><div class="co-actions"><button data-co-refresh>刷新清单</button><button data-co-add>新增要求</button>${d.template?.available?'<button data-co-template>添加标准检查项</button>':''}</div></div>${coCommon(v)}<div class="co-stats">${['missing','pending','checked','stale'].map(k=>`<span>${coStatus[k]} ${h(d.counts?.[k]??0)}</span>`).join('')}</div><div class="co-layout"><div>${(d.items||[]).map(i=>`<article class="co-record"><div class="co-meta"><span class="co-state" data-state="${h(i.status)}">${h(coStatus[i.status]||i.status)}</span><span>${i.required?'必要内容':'可选内容'}</span></div><h3>${h(i.title)}</h3><p>${h(i.requirement)}</p>${i.note?`<p>${h(i.note)}</p>`:''}${i.stale_reasons?.length?`<p class="co-error">${h(i.stale_reasons.join('；'))}</p>`:''}${i.withdrawn?`<p>撤回原因：${h(i.withdraw_reason)}</p>`:''}${i.verification?`<p class="co-note">${h(i.verification.actor)} · ${h(i.verification.created)}<br>${h(i.verification.note)}</p>`:''}${i.artifact_id?coSource('查看绑定材料：'+(((d.artifacts||[]).find(a=>a.id===i.artifact_id)||{}).title||'')+' · v'+(((d.artifacts||[]).find(a=>a.id===i.artifact_id)||{}).version??'未知'),((d.artifacts||[]).find(a=>a.id===i.artifact_id)||{}).body||'材料暂不可读取'):''}<div class="co-actions">${!i.withdrawn?`<button data-co-item="${h(i.id)}" data-co-act="update">调整要求与材料</button><button data-co-item="${h(i.id)}" data-co-act="verify" ${i.can_verify?'':'disabled'}>核对这份材料</button><button data-co-item="${h(i.id)}" data-co-act="withdraw">撤回要求</button>`:''}</div></article>`).join('')||'<p class="co-empty">尚未登记内容要求。可手动添加，或主动选择标准检查项；空清单不表示完整交付。</p>'}</div><aside class="co-panel"><h3>${{add:'新增内容要求',update:'调整内容要求',verify:'核对固定材料',withdraw:'撤回内容要求'}[action]}</h3><form class="co-form" data-co-form>${editing?coField('title','内容标题',draft.title)+coField('requirement','需要覆盖什么',draft.requirement,'textarea')+`<label class="co-check"><input data-co-field="required" type="checkbox" ${draft.required?'checked':''}>必要内容</label><label>对应材料<select data-co-field="artifact_id"><option value="">尚未提供</option>${(d.artifacts||[]).filter(a=>a.current||String(a.id)===String(draft.artifact_id)).map(a=>`<option value="${h(a.id)}" ${String(a.id)===String(draft.artifact_id)?'selected':''}>${h(a.title)} · v${h(a.version)}${a.current?'':'（旧版）'}</option>`).join('')}</select></label>`:`<p>${h(item?.title||'请选择清单项目')}</p>`}${coField('note',action==='verify'?'核对了什么、依据是什么':action==='withdraw'?'撤回原因':'补充说明',draft.note,'textarea')}${coEditorState(v,draft,allowed,token)}<button data-co-write class="primary">${action==='verify'?'登记材料核对':action==='withdraw'?'记录撤回':'保存内容要求'}</button></form></aside></div>${coSource('完整检查历史',d.history||[])}</section>`;
 coFinishForm(v,draft,allowed,fields=>coWrite(v,{action,revision:fields.revision,...(action==='add'?{}:{item_id:fields.item_id}),...(editing?{title:fields.title,requirement:fields.requirement,required:fields.required,artifact_id:fields.artifact_id?Number(fields.artifact_id):null,note:fields.note}:{note:fields.note,...(action==='verify'?{source_token:fields.source_token}:{})})}),token);
 v.host.querySelector('[data-co-add]').onclick=()=>coverageEdit(v);v.host.querySelectorAll('[data-co-item]').forEach(b=>{b.disabled=b.disabled||!d.can_edit||!coWritable(v.project)||!!coPending(v.key);b.onclick=()=>coverageEdit(v,d.items.find(i=>String(i.id)===b.dataset.coItem),b.dataset.coAct)});const template=v.host.querySelector('[data-co-template]');if(template){template.disabled=!d.can_edit||!coWritable(v.project)||!!coPending(v.key);template.onclick=()=>coWrite(v,{action:'seed_template',revision:d.revision,template_id:d.template.id},null,true)}v.host.querySelector('[data-co-add]').disabled=!d.can_edit||!coWritable(v.project)||!!coPending(v.key);
}
function deliveryContentCreateBind(){const host=$('#dlCreate'),project=$('#dlProject')?.value;if(!host||!project||project==='__new')return;let v=COORD.views.get(coIdentity(project,'content_create','new'));if(!v||!coLive(v)||v.host!==host){v=coView(host,project,'content_create','new','/api/delivery-content',deliveryContentCreatePaint);v.data={revision:0}}deliveryContentCreatePaint(v);return v}
function deliveryContentCreatePaint(v){if(!coLive(v))return;let status=v.host.querySelector('[data-co-create-state]');if(!status){status=document.createElement('div');status.setAttribute('data-co-create-state','');v.host.appendChild(status)}status.innerHTML=coCommon(v);const pending=coPending(v.key),retry=status.querySelector('[data-co-retry]');if(retry)retry.onclick=()=>coPerform(v,pending);v.host.querySelectorAll('input,select,textarea').forEach(el=>{if(pending){el.dataset.coPendingDisabled='true';el.disabled=true}else if(el.dataset.coPendingDisabled){el.disabled=false;delete el.dataset.coPendingDisabled}});const button=$('#dlCreateGo');if(button)button.disabled=!!pending||!coWritable(v.project)}
async function deliveryContentCreate(project,draft){const v=deliveryContentCreateBind();if(!v||v.project!==project)throw Error('请先选择当前项目再创建交付。');return coWrite(v,{action:'create',revision:0,project,type:draft.type,title:draft.title,goal:draft.goal})}
function deliveryContentOpen(host,delivery,stage){const v=coView(host,delivery.project,'content',delivery.id+'/'+stage,'/api/deliveries/'+encodeURIComponent(delivery.id)+'/content',deliveryContentPaint,()=>DL.detail?.delivery.id===delivery.id);v.deliveryId=delivery.id;v.stage=stage;host.innerHTML='<p class="co-note">正在读取手工材料及固定版本…</p>';v.ready=coRefresh(v);return v}
function deliveryContentPaint(v){const d=v.data;if(!d)return;const stage=(d.stages||[]).find(s=>s.key===v.stage);if(!stage){v.host.innerHTML='<p class="co-error">当前交付没有这个阶段，请刷新交付记录。</p>';return}const a=stage.artifact,legacy=typeof dlRead==='function'?dlRead('tmh.delivery.artifact.'+v.deliveryId+'.'+v.stage,null):null,draft=coDraft(v,{revision:legacy?-1:d.revision,source_token:legacy?'':d.source_token,title:legacy?.title||a?.title||stage.name,body:legacy?.body??a?.body??'',_originalBody:legacy?.body??a?.body??'',_legacy:!!legacy}),allowed=d.can_edit&&stage.can_save;
 v.host.innerHTML=`<div class="co-panel"><div class="co-head"><div><h2>阶段手工材料</h2><p class="co-note">保存完整文字与材料版本；不运行模型、测试或发布。</p></div><button data-co-refresh>刷新材料</button></div>${coCommon(v)}${draft._legacy?'<p class="co-note">已恢复升级前的完整编辑草稿，请核对最新材料并明确绑定当前依据后保存。</p>':''}${a?`<p class="co-meta">${h(a.title)} · 版本 ${h(a.version)}</p>${coSource('查看这版完整材料',a.body)}`:'<p class="co-empty">尚未保存手工材料。可先登记研究、方案或实际验证依据。</p>'}<form class="co-form" data-co-form>${coField('title','材料标题',draft.title)}${coField('body','完整材料正文',draft.body,'textarea','class="co-source-input"')}${coEditorState(v,draft,allowed,d.source_token)}<button class="primary" data-co-write>保存材料新版本</button></form>${(stage.history||[]).map(a=>coSource('历史版本 '+a.version+' · '+a.title,a.body)).join('')}</div>`;
 coFinishForm(v,draft,allowed,f=>coWrite(v,{action:'save_artifact',revision:f.revision,source_token:f.source_token,stage:v.stage,title:f.title,body:f.body}),d.source_token);
}
"""
